          <div class="mini"><div class="lbl">LEVEL</div><div class="v" id="levelVal">1</div></div>
          <div class="mini lives"><div class="lbl">LIVES</div><div class="v" id="livesVal">●●●</div></div>
          <div class="mini"><div class="lbl">BEST</div><div class="v" id="bestVal" style="color:var(--amber)">0</div></div>
        </div>
